INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52911, 'Micah 1:12', 'Micah', 1, 12, 'د ماروت خلک په پرېشانۍ سره د ارامۍ د راتللو انتظار کوي، ځکه چې څښتن مصیبت د اورشلیم تر دروازو پورې رارسولی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_12.mp3', '', 1761754199, 1761754199),
(52912, 'Micah 1:13', 'Micah', 1, 13, 'ای د لاخیش اوسېدونکو، په اسونو پسې جنګي ګاډۍ وتړئ او وتښتئ. تاسو د اسراییلو د ګناهونو پیروي وکړه او اورشلیم مو ګناه ته راوکاږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_13.mp3', '', 1761754199, 1761754199),
(52913, 'Micah 1:14', 'Micah', 1, 14, 'ای د یهودا خلکو، د مورشت‌جت د ښارګوټي سره خدای پاماني وکړئ. د اسراییلو پاچاهانو ته د اکزیب د ښارګوټي څخه مرسته نه رارسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_14.mp3', '', 1761754199, 1761754199),
(52914, 'Micah 1:15', 'Micah', 1, 15, 'ای د مریشې خلکو، څښتن به تاسو هغه دښمن ته په لاس ورکړي چې غواړي ستاسو ښارګوټی ونیسي. د اسراییلو مشران به لاړ شي او د عدولام په سمڅه کې به پټ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_15.mp3', '', 1761754199, 1761754199),
(52915, 'Micah 1:16', 'Micah', 1, 16, 'ای د یهودا خلکو، د خپلو خوږو اولادونو له غمه خپل سرونه وخرایئ او خپل ځانونه د ټپوسانو په شان ګنجیان کړئ، ځکه چې ستاسو اولادونه به ستاسو نه لېرې وطنونو ته جلاوطنه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_16.mp3', '', 1761754199, 1761754199),
(52916, 'Isaiah 60:1', 'Isaiah', 60, 1, 'پاڅه او وځلېږه ځکه رڼا ده ځلېدلې په تا او ځلېدلی دی جلال د څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_1.mp3', '', 1761754199, 1761754199),
(52917, 'Isaiah 60:2', 'Isaiah', 60, 2, 'ګوره، خوره شوې ده تیاره په ټوله ځمکه باندې نور قومونه دي پټ شوي تورې تیارې لاندې خو د څښتن رڼا به راشي په تا باندې او ستا دپاسه به ښکاره شي د هغه جلال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_2.mp3', '', 1761754199, 1761754199),
(52918, 'Isaiah 60:3', 'Isaiah', 60, 3, 'قومونه رابه شي چې وویني رڼا ستا پاچاهان به راشي چې وویني ستا ځلېدونکې رڼا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_3.mp3', '', 1761754199, 1761754199),
(52919, 'Isaiah 60:4', 'Isaiah', 60, 4, 'وګوره شاوخوا ته او نظر وکړه چې څه پېښیږي! راغونډیږي ستا ټول خلک او ستا خواته راروان دي ستا زامن راځي له ډېر لېرې ځایه او ستا لوڼې به د ماشومانو په شان په غېږ کې یووړل شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_4.mp3', '', 1761754199, 1761754199),
(52920, 'Isaiah 60:5', 'Isaiah', 60, 5, 'نو بیا به ته ووینې دا صحنه او له خوشحالۍ به ډک شې له هیجانه نه به درزیږي ستا زړه ځکه تاته به راشي د بحیرې له لارې د نورو قومونو شتمني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_5.mp3', '', 1761754199, 1761754199),
(52921, 'Isaiah 60:6', 'Isaiah', 60, 6, 'رابه شي له عیفا او له مدیانه لوی کاروانونه د اوښانو او پټه به کړي ځمکه ستا هغوی به راوړي سره زر او قیمتي خوشبویي له شیبا نه له خپل ځانه سره وربه کړي زېری خلکو ته د څښتن د کارو او هم به وکړي د هغه ستاینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_6.mp3', '', 1761754199, 1761754199),
(52922, 'Isaiah 60:7', 'Isaiah', 60, 7, 'تاته به راوړل شي ټولې رمې د قیدار ستا خدمت ته به حاضر کړای شي د نبایوت پسونه هغوی به خپله لاړ شي د څښتن د قربانۍ ځای ته او هغه به ومني دا قرباني څښتن به نور هم ښایسته کړي خپل پرتمین کور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_7.mp3', '', 1761754199, 1761754199),
(52923, 'Isaiah 60:8', 'Isaiah', 60, 8, 'دا څوک دي چې روان دي لکه د ورېځو په شان او راستنیږي خپلو ځالو ته لکه کوترو په شان؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_8.mp3', '', 1761754199, 1761754199),
(52924, 'Isaiah 60:9', 'Isaiah', 60, 9, 'وي به څښتن ته انتظار لېرې ملکونه دي راروانې مخکې کشتۍ د بحیرې چې راستانه کړي خپل هېواد ته ستا خلک لېرې ځایونو څخه هغوی راځي د خپلو سرو او سپینو زرو سره کړي په دې ډول درناوی ستا د څښتن د نوم چې دی سپېڅلی د اسراییلو خدای ځکه ورکړی دی خپل قوم ته هغه شان او شوکت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_9.mp3', '', 1761754199, 1761754199),
(52925, 'Isaiah 60:10', 'Isaiah', 60, 10, 'څښتن وایي اورشلیم ته: «پردي خلک به بیا ودان کړي دېوالونه ستا او پاچاهان به د هغوی وکړي خدمت ستا که څه هم ما په قهر کې سزا درکړله تاته خو اوس به رحم د خپلې مهربانۍ وښایم تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_10.mp3', '', 1761754199, 1761754199),
(52926, 'Isaiah 60:11', 'Isaiah', 60, 11, 'شپه او ورځ به وي خلاصې دروازې ستا او هغه به نه بندیږي هېڅکله ترڅو راوړل شي شتمني د نورو قومونو تاته او پاچاهان به د هغوی راوستل شي لکه بندیانو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_11.mp3', '', 1761754199, 1761754199),
(52927, 'Isaiah 60:12', 'Isaiah', 60, 12, 'خو که چېرې وکړي کوم قومونه او پاچاهۍ ستا له خدمته انکار له منځه لاړ به شي بیخي او شي تباه به هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_12.mp3', '', 1761754199, 1761754199),
(52928, 'Isaiah 60:13', 'Isaiah', 60, 13, 'د لبنان شان او شوکت به راشي تاته تاته به راوړل شي له هغه ځایه لرګي د سروې، سپېدار او نښتر د ونو ترڅو ښکلی او سینګار کړي زما د عبادت ځای زه به ورکړمه جلال دې ځای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_13.mp3', '', 1761754199, 1761754199),
(52929, 'Isaiah 60:14', 'Isaiah', 60, 14, 'کومو خلکو چې دی کړی په تا ظلم اولاده به د هغوی راشي او شي به ټیټ ستا په وړاندې هرچا چې تاته سپکاوی کړی دی هغوی به ولویږي ستا پښو ته هغوی به یاد کړي تا د څښتن د ښار په نامه یعنې ښار د اسراییلو د سپېڅلي خدای چې صهیون دی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_14.mp3', '', 1761754199, 1761754199),
(52930, 'Isaiah 60:15', 'Isaiah', 60, 15, 'ته رد شوی وې یو وخت او کرکه کوله خلکو ستا نه هېچا به نه کاوه سفر د ستا په لاره خو اوس به زه تا پرتمین کړمه د تل دپاره تانه به جوړ کړم د خوشحالۍ ځای ټولو نسلونو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_15.mp3', '', 1761754199, 1761754199),
(52931, 'Isaiah 60:16', 'Isaiah', 60, 16, 'داسې ګټه به ترلاسه کړې د پردیو قومونو او پاچاهانو څخه لکه ماشوم چې روي د خپلې مور تی بیا به ته پوه شې چې زه څښتن یمه ژغورونکی ستا او قادر خدای یم د یعقوب چې خلاصون درکوم تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_16.mp3', '', 1761754199, 1761754199),
(52932, 'Isaiah 60:17', 'Isaiah', 60, 17, 'زه به راوړم تاته په ځای د برنجو سره زر په ځای د اوسپنې سپین زر برنج د لرګیو په ځای او اوسپنه د تیږو په ځای ستا حاکمان به راولي سوله او د انصاف او عدالت نه به کړي جوړه خپله دنده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_17.mp3', '', 1761754199, 1761754199),
(52933, 'Isaiah 60:18', 'Isaiah', 60, 18, 'نور به د ظلم اواز نه وي ستا هېواد کې ستا وطن به تباهي نه کړي ټوټې ټوټې دېوالونه به خوندي ساتي تا او هغه خلک چې ننوځي هلته، کوي ستاینه به ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_18.mp3', '', 1761754199, 1761754199),
(52934, 'Isaiah 60:19', 'Isaiah', 60, 19, 'ته به نور نه لرې اړتیا د ورځې د لمر رڼا ته او نه به د شپې لرې اړتیا د سپوږمۍ ځلا ته ځکه زه څښتن، ستا خدای به تل یمه رڼا ستا په تا به وځلیږي زما د جلال رڼا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_19.mp3', '', 1761754199, 1761754199),
(52935, 'Isaiah 60:20', 'Isaiah', 60, 20, 'نور به نه پرېوځي ستا لمر او نه به کوزیږي ستا سپوږمۍ ځکه زه څښتن به ابدي رڼا یم ستا او پای ته به ورسي د غم ورځې ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_20.mp3', '', 1761754199, 1761754199),
(52936, 'Isaiah 60:21', 'Isaiah', 60, 21, 'ستا ټول خلک به وي نېک او تل به وي د خپل هېواد خاوندان ما کرلي دي هغوی لکه نیالګیو په شان خپلو لاسونو باندې ترڅو ښکاره کړم ټولو ته خپله لویي او جلال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_21.mp3', '', 1761754199, 1761754199),
(52937, 'Isaiah 60:22', 'Isaiah', 60, 22, 'ستا له کوچنۍ او له بې وسه کورنۍ نه به قبیله نه بلکې لوی او قوي قوم جوړ شي زه چې څښتن یم په مناسب وخت کې به ډېر زر سرته ورسوم دا کار»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah60_verse_22.mp3', '', 1761754199, 1761754199),
(52938, 'Job 32:1', 'Job', 32, 1, 'نو دې درېو کسانو ايُوب له نور جواب ورنۀ کړو، ځکه چې ايُوب پخپله په خپل خيال کښې بې‌ګناه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_1.mp3', '', 1761754199, 1761754199),
(52939, 'Job 32:2', 'Job', 32, 2, 'نو بيا د رام د خاندان د بوزى براکيل زوئ اليهُو غصه شو. هغه ايُوب ته ځکه غصه شو چې ايُوب خپل ځان صحيح ګڼلو او په خُدائ پاک يې اِلزام لګولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_2.mp3', '', 1761754199, 1761754199),
(52940, 'Job 32:3', 'Job', 32, 3, 'هغه د ايُوب درېو ملګرو ته هم غصه وو ځکه چې هغوئ ايُوب له جواب نۀ شو ورکولے او داسې ښکارېده چې خُدائ پاک په غلطه دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_3.mp3', '', 1761754199, 1761754199),
(52941, 'Job 32:4', 'Job', 32, 4, 'نو اليهُو د ايُوب سره د خبرو کولو دپاره د نورو کسانو انتظار کولو، ځکه چې هغوئ د هغۀ نه مشران وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_4.mp3', '', 1761754199, 1761754199),
(52942, 'Job 32:5', 'Job', 32, 5, 'خو چې کله اليهُو ته پته ولګېده چې د هغه درېو کسانو سره څۀ جواب نۀ وو، نو هغه غصه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_5.mp3', '', 1761754199, 1761754199),
(52943, 'Job 32:6', 'Job', 32, 6, 'د بوزى براکيل زوئ اليهُو ووئيل، ”زۀ زلمے يم، او تۀ بوډا يې، نو په دې وجه زۀ يرېدم چې تا د خپلې رايې نه خبر کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_6.mp3', '', 1761754199, 1761754199),
(52944, 'Job 32:7', 'Job', 32, 7, 'ما وئيل چې مشران دې خبره وکړى، ځکه چې عقل د عُمر سره راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_7.mp3', '', 1761754199, 1761754199),
(52945, 'Job 32:8', 'Job', 32, 8, 'دا د قادر خُدائ روح دے چې بنيادم له پوهه ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_8.mp3', '', 1761754199, 1761754199),
(52946, 'Job 32:9', 'Job', 32, 9, 'صِرف مشران هوښيار نۀ وى، کله کله مشران هم په اِنصاف باندې نۀ پوهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_9.mp3', '', 1761754199, 1761754199),
(52947, 'Job 32:10', 'Job', 32, 10, 'نو ځکه زۀ وايم چې ما ته غوږ ونيسئ، ما پرېږدئ چې د خپلې رايې اظهار هم وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_10.mp3', '', 1761754199, 1761754199),
(52948, 'Job 32:11', 'Job', 32, 11, 'ګوره، کله چې تا خبرې کولې نو ما څۀ نۀ وئيل، او ما ستا دليل ته غوږ نيولو، کله به چې تا سوچ کولو چې څۀ ووايم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_11.mp3', '', 1761754199, 1761754199),
(52949, 'Job 32:12', 'Job', 32, 12, 'ما تا ته توجو کوله، خو داسې هيڅ څوک نۀ وُو چې ايُوب يې غلط ثابت کړے وے، او په تاسو کښې داسې هيڅ څوک نۀ وُو چې د هغۀ د خبرې جواب يې ورکړے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_12.mp3', '', 1761754199, 1761754199),
(52950, 'Job 32:13', 'Job', 32, 13, 'نو بيا دا مۀ وايئ چې مونږ ته عقل مِلاو شوے دے، پرېږده چې د انسان په ځائ خُدائ پاک هغۀ له جواب ورکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_13.mp3', '', 1761754199, 1761754199),
(52951, 'Job 32:14', 'Job', 32, 14, 'ايُوب ما سره نۀ تاسو سره بحث کولو، خو زۀ به هغۀ له ستاسو په شان جواب نۀ ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_14.mp3', '', 1761754199, 1761754199),
(52952, 'Job 32:15', 'Job', 32, 15, 'تاسو غلى ناست يئ، تاسو سره بل جواب نشته، تاسو يوه خبره هم نۀ شئ کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_15.mp3', '', 1761754199, 1761754199),
(52953, 'Job 32:16', 'Job', 32, 16, 'کله چې تاسو خاموش يئ نو زۀ به هم خاموش يم؟ ځکه چې تاسو هلته ولاړ يئ او بله يوه خبره هم نۀ شئ کولے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_16.mp3', '', 1761754199, 1761754199),
(52954, 'Job 32:17', 'Job', 32, 17, 'زۀ به هم خپل جواب ورکړم، زۀ به هم د خپلې رايې اظهار وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_17.mp3', '', 1761754199, 1761754199),
(52955, 'Job 32:18', 'Job', 32, 18, 'ځکه چې ما سره خبرې ډېرې دى، په ما کښې چې کوم روح دے هغه ما مجبوروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_18.mp3', '', 1761754199, 1761754199),
(52956, 'Job 32:19', 'Job', 32, 19, 'کۀ ما ته د خبرو کولو موقع مِلاو نۀ شى، نو زما برداشت ختم دے او زۀ به پړق وچوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_19.mp3', '', 1761754199, 1761754199),
(52957, 'Job 32:20', 'Job', 32, 20, 'زۀ به خبرې کوم، چې ما ته آرام مِلاو شى، او زۀ به جواب درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_20.mp3', '', 1761754199, 1761754199),
(52958, 'Job 32:21', 'Job', 32, 21, 'زۀ به د هيچا طرفدارى نۀ کوم او زۀ به د چا چاپلوسى نۀ کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_21.mp3', '', 1761754199, 1761754199),
(52959, 'Job 32:22', 'Job', 32, 22, 'ځکه چې زۀ په چاپلوسۍ نۀ پوهېږم، ګنې زما پېدا کوونکى به زر ختم کړے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job32_verse_22.mp3', '', 1761754199, 1761754199),
(52960, 'Isaiah 57:1', 'Isaiah', 57, 1, 'هېڅوک د نېکو خلکو د مړینې پروا نه ساتي. کله چې هغوی مړه شي د مړینې په دلیل یې څوک نه پوهیږي. هغوی په دې خاطر مري، ترڅو له راروانې بلا څخه وژغورل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_1.mp3', '', 1761754199, 1761754199),
(52961, 'Isaiah 57:2', 'Isaiah', 57, 2, 'څوک چې نېکه لاره غوره کوي او مري، د هغوی دپاره مړینه سلامتي او ارامي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_2.mp3', '', 1761754199, 1761754199),
(52962, 'Isaiah 57:3', 'Isaiah', 57, 3, 'ای کوډګرو، زناکارانو او فاسدو خلکو، دلته راشئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_3.mp3', '', 1761754199, 1761754199),
(52963, 'Isaiah 57:4', 'Isaiah', 57, 4, 'تاسو د ژبې په ویستلو په چا ملنډې وهئ؟ تاسو سرکښ او غولوونکي نه یئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_4.mp3', '', 1761754199, 1761754199),
(52964, 'Isaiah 57:5', 'Isaiah', 57, 5, 'تاسو د بتانو داسې عبادت کوئ، لکه څنګه چې د سپېڅلو څېړیو او هرې شنې ونې لاندې زنا کوئ. تاسو خپل اولادونه په وچو ویالو او د ګټو په غارونو کې قرباني کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_5.mp3', '', 1761754199, 1761754199),
(52965, 'Isaiah 57:6', 'Isaiah', 57, 6, 'تاسو د هغو ځایونو نه ښویې تیږې را اخلئ، خپل ځان ته بتان جوړوئ او د خدایانو په توګه ورته عبادت کوئ. تاسو هغوی ته د څښلو نذرانې توی کړې دي او د غلو دانو نذرانې مو ورته راوړې دي. ایا دا ټول شیان ومنم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_6.mp3', '', 1761754199, 1761754199),
(52966, 'Isaiah 57:7', 'Isaiah', 57, 7, 'تاسو لوړو غرونو ته ځئ، بتانو ته نذرانې وړاندې کوئ او هلته زنا کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_7.mp3', '', 1761754199, 1761754199),
(52967, 'Isaiah 57:8', 'Isaiah', 57, 8, 'د تړلو دروازو تر شا مو بتان ودرولي دي او زه مو پریښی یم. ځانونه لوڅوئ، د خپلو معشوقو سره په یوه بستره کې څملئ، هغوی سره لوظ کوئ او په دې ډول خپل هوس پوره کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_8.mp3', '', 1761754199, 1761754199),
(52968, 'Isaiah 57:9', 'Isaiah', 57, 9, 'تاسو د مولک بت ته د تېلو سوغات وړاندې کوئ او په ځان باندې ډېر عطرونه وهئ. د دې دپاره چې نور خدایان پیدا کړئ، نو خپل استازي ډېرو لېرې ځایونو، حتی د مړو دنیا ته لېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_9.mp3', '', 1761754199, 1761754199),
(52969, 'Isaiah 57:10', 'Isaiah', 57, 10, 'تاسو د نورو خدایانو په لټولو سره خپل ځانونه ستړي کړل، خو تاسو ونه ویل چې دا کار بې ګټې دی. تاسو د هغوی په لټون کې نوی قوت پیدا کړ او کمزوري نه شوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_10.mp3', '', 1761754199, 1761754199),
(52970, 'Isaiah 57:11', 'Isaiah', 57, 11, 'څښتن وایي: «دا خدای څوک دی چې تاسو ورڅخه دومره وېرېږئ، ماته دروغ وایئ او ما بیخي هېروئ؟ په دې خاطر چې زه ډېره موده غلی پاتې وم، زما څخه نه وېرېږئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_11.mp3', '', 1761754199, 1761754199),
(52971, 'Isaiah 57:12', 'Isaiah', 57, 12, 'تاسو فکر کوئ چې ستاسو کارونه عادلانه دي، خو زه به ستاسو بد عملونه خلکو ته څرګند کړم. دا کارونه به تاسو سره کومه مرسته ونه شي کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_12.mp3', '', 1761754199, 1761754199),
(52972, 'Isaiah 57:13', 'Isaiah', 57, 13, 'کله چې تاسو د مرستې دپاره چیغې وهئ، نو پرېږدئ چې ستاسو بتان تاسو وژغوري! ځکه حتی یو نرم باد به هغوی ټول لېرې یوسي! خو څوک چې ماته پناه راوړي، هغوی به د دې هېواد او زما د سپېڅلي غره وارثان وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_13.mp3', '', 1761754199, 1761754199),
(52973, 'Isaiah 57:14', 'Isaiah', 57, 14, 'څښتن وایي: «لاره جوړه کړئ، لاره جوړه کړئ! زما د خلکو د لارې څخه هر خنډ لرې کړئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_14.mp3', '', 1761754199, 1761754199),
(52974, 'Isaiah 57:15', 'Isaiah', 57, 15, 'ځکه خدای تعالی چې ډېر لوړ، تل ترتله ژوندی او نوم یې سپېڅلی دی، داسې وایي: «زه په لوړ او سپېڅلي ځای کې اوسېږم، خو زه د هغو خلکو سره هم اوسېږم چې توبه ګاره او عاجزان دي، ترڅو د عاجزو خلکو باور په ځای کړم او د توبه ګارانو هیله بېرته راژوندۍ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_15.mp3', '', 1761754199, 1761754199),
(52975, 'Isaiah 57:16', 'Isaiah', 57, 16, 'زه به تل په خپل قوم باندې تور نه لګوم او نه به ورباندې په قهرېږم، ځکه که داسې مې وکړل، نو د خلکو نه به روح او ساه ووځي یعنې هغه ژوندون ورکوونکې ساه چې ما پیدا کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_16.mp3', '', 1761754199, 1761754199),
(52976, 'Isaiah 57:17', 'Isaiah', 57, 17, 'زه په هغوی د دوی د حریصتوب په خاطر په قهر وم، نو ځکه مې هغوی ته سزا ورکړه او مخ مې ورڅخه واړاوه. خو هغوی مرتد خلک وو او د ګناه لاره یې پرېنښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_17.mp3', '', 1761754199, 1761754199),
(52977, 'Isaiah 57:18', 'Isaiah', 57, 18, 'ما ولیدل چې زما خلکو څه کول، خو زه به هغوی ته شفا ورکړم. زه به دوی ته لارښوونه وکړم او تسلي به ورته ورکړم. ویرجنو خلکو ته به هم تسلي ورکړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_18.mp3', '', 1761754199, 1761754199),
(52978, 'Isaiah 57:19', 'Isaiah', 57, 19, 'او دوی به دې ته وهڅوم چې زما ثنا او صفت وکړي. زه به ټولو ته که نژدې وي یا لېرې، سوله او سلامتي ور په برخه کړم او خپلو خلکو ته به شفا ورکړم!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_19.mp3', '', 1761754199, 1761754199),
(52979, 'Isaiah 57:20', 'Isaiah', 57, 20, 'خو بدکاره خلک د هغه توفاني بحیرې په شان دي چې غرهار یې هېڅکله درېدلی نه شي او اوبه یې چټلي او خټې له ځانه سره راوړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_20.mp3', '', 1761754199, 1761754199),
(52980, 'Isaiah 57:21', 'Isaiah', 57, 21, 'زما خدای وایي: «د بد عملو خلکو دپاره سوله نشته.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah57_verse_21.mp3', '', 1761754199, 1761754199),
(52981, 'Daniel 12:1', 'Daniel', 12, 1, 'په هغه وخت کښې به ميکائيل، د فرښتو لوئ سردار څوک چې ستا د قوم حفاظت کوى، راوچت شى. هغه به داسې د مصيبت وخت وى چې داسې به د قومونو د پېدايښت نه تر دې وخت پورې نۀ وى شوے. خو په هغه وخت کښې به ستا د قوم نه هغوئ بچ شى، د چا نوم چې د خُدائ پاک په کِتاب کښې ليکلے شوے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_1.mp3', '', 1761754199, 1761754199),
(52982, 'Daniel 12:2', 'Daniel', 12, 2, 'نو بيا به هغه ګڼ خلق څوک چې په خاورو کښې پراتۀ دى راپاڅى، څوک به د ابدى ژوند دپاره، او څوک د رسوائى او ابدى شرم دپاره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_2.mp3', '', 1761754199, 1761754199),
(52983, 'Daniel 12:3', 'Daniel', 12, 3, 'څوک چې هوښيار دى د نمر د شغلو په شان به ځليږى، او هغوئ څوک چې ډېرو خلقو ته د صداقت لارښودنه کوى، هغوئ به لکه د ستورو په شان د تل دپاره ځليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_3.mp3', '', 1761754199, 1761754199),
(52984, 'Daniel 12:4', 'Daniel', 12, 4, 'خو تۀ اے دانياله، دا کلام بند کړه او تر آخرى زمانې پورې پرې مهر ولګوه. ډېر خلق به اخوا ديخوا ګرځى چې خپل عِلم کښې اضافه وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_4.mp3', '', 1761754199, 1761754199),
(52985, 'Daniel 12:5', 'Daniel', 12, 5, 'بيا ما دانيال وکتل چې زما په وړاندې دوه نور سړى ولاړ وُو، يو د سيند په دې غاړه او بل پورې غاړه ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_5.mp3', '', 1761754199, 1761754199),
(52986, 'Daniel 12:6', 'Daniel', 12, 6, 'په هغوئ کښې يو د هغه سړى نه تپوس وکړو چې د کتان جامې يې اغوستې وې، او څوک چې د اوبو په غاړه ولاړ وو، ”نو دا حېرانېدونکې خبرې به نور په څومره وخت کښې پوره شى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_6.mp3', '', 1761754199, 1761754199),
(52987, 'Daniel 12:7', 'Daniel', 12, 7, 'د کتان د جامو والا سړى څوک چې د اوبو دپاسه وو هغۀ خپل دواړه لاسونه آسمان ته اوچت کړل او ما واورېدل چې هغۀ د ژوندى خُدائ پاک په نوم قسم وخوړو او وې فرمائيل، ”دا به د درې نيمو کالو پورې وى. کله چې په مقدسو خلقو ظلم ختم شى نو بيا به دا هر څۀ سر ته ورسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_7.mp3', '', 1761754199, 1761754199),
(52988, 'Daniel 12:8', 'Daniel', 12, 8, 'ما دا هر څۀ واورېدل، خو پوهه پرې نۀ شوم. نو ما ترې تپوس وکړو، ”زما مالِکه، د دې ټولو خبرو به څۀ اَنجام وى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_8.mp3', '', 1761754199, 1761754199),
(52989, 'Daniel 12:9', 'Daniel', 12, 9, 'نو هغۀ جواب راکړو، ”اے دانياله، په خپله لار په آرام سره لاړ شه، ځکه چې تر آخره وخته پورې به کلام بند شى او مهر به پرې لګېدلے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_9.mp3', '', 1761754199, 1761754199),
(52990, 'Daniel 12:10', 'Daniel', 12, 10, 'ډېر به پاک، بې‌داغه او صفا کړے شى، خو بدعمله به بدعمله پاتې شى. يو بدعمله به پرې هم پوهه نۀ شى، خو هغوئ څوک چې هوښيار دى، هغوئ به پرې پوهه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_10.mp3', '', 1761754199, 1761754199),
(52991, 'Daniel 12:11', 'Daniel', 12, 11, 'د کوم وخت نه چې د روزانه قربانۍ ختمې شوې دى او د تباهۍ ناپاکه بُت اېښودے شوے دے، د هغې نه به دولس سوه او نوى ورځې تېرې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_11.mp3', '', 1761754199, 1761754199),
(52992, 'Daniel 12:12', 'Daniel', 12, 12, 'بختور دى هغوئ څوک چې ديارلس سوه او پينځۀ دېرش ورځو ختمېدو پورې صبر وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_12.mp3', '', 1761754199, 1761754199),
(52993, 'Daniel 12:13', 'Daniel', 12, 13, 'ترڅو چې ستا تعلق دے په خپله لار تر آخره لاړ شه. تۀ به وفات شې، نو تۀ به په آخرى ورځو کښې بيا راژوندے شې د دې دپاره چې خپل ميراث درته مِلاو شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel12_verse_13.mp3', '', 1761754199, 1761754199),
(52994, 'Job 3:1', 'Job', 3, 1, 'د هغې نه پس ايُوب خبرې شروع کړې او چې په کومه ورځ باندې هغه پېدا شوے وو په هغې يې لعنت ووئيلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_1.mp3', '', 1761754199, 1761754199),
(52995, 'Job 3:2', 'Job', 3, 2, 'ايُوب وفرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_2.mp3', '', 1761754199, 1761754199),
(52996, 'Job 3:3', 'Job', 3, 3, '”هغه ورځ دې تباه شى چې په کومه ورځ باندې زۀ پېدا شوے وم او چې په کومه شپه زۀ د مور په ګېډه شوے وم نو هغه شپه د‌ې لعنتى شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_3.mp3', '', 1761754199, 1761754199),
(52997, 'Job 3:4', 'Job', 3, 4, 'هغه ورځ دې تکه توره شى. لوئ خُدائ پاک دې پرې نظر نۀ اچوى، او رڼا دې پرې نۀ راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_4.mp3', '', 1761754199, 1761754199),
(52998, 'Job 3:5', 'Job', 3, 5, 'توره دې شى او تکه توره تيارۀ دې پرې راشى. وريځې دې ورباندې پاتې شى، د هغه ورځې تيارۀ دې دا ويروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_5.mp3', '', 1761754199, 1761754199),
(52999, 'Job 3:6', 'Job', 3, 6, 'تکه توره تيارۀ دې هغه شپه قابو کړى. هغه دې بيا هيڅکله د کال په ورځو کښې نۀ شى شمېرلے او په يوه مياشت کښې دې هم حِساب نۀ کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_6.mp3', '', 1761754199, 1761754199),
(53000, 'Job 3:7', 'Job', 3, 7, 'او هغه شپه دې شنډه شى، په هغه شپه کښې دې هيڅ خوشحالى نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_7.mp3', '', 1761754199, 1761754199),
(53001, 'Job 3:8', 'Job', 3, 8, 'لعنت ويونکى دې هم په هغه ورځ لعنت ووائى، هغه څوک چې په سمندرى بلاګانو راويښولو کښې ماهِر وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_8.mp3', '', 1761754199, 1761754199),
(53002, 'Job 3:9', 'Job', 3, 9, 'د دې د سحر ستورى دې تور شى، هغه دې د رڼا په طمع وى، خو مِلاو دې ورته نۀ شى، دا دې په سحر کښې د نمر شُغلې ونۀ وينى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_9.mp3', '', 1761754199, 1761754199),
(53003, 'Job 3:10', 'Job', 3, 10, 'لعنت دې وى په هغه شپه چې زما د مور حمل يې کېدو ته پرېښودو، او زۀ يې د دې ټولو مصيبتونو دپاره پېدا کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_10.mp3', '', 1761754199, 1761754199),
(53004, 'Job 3:11', 'Job', 3, 11, 'زۀ د پېدا کېدو په وخت ولې مړ نۀ شوم، او د زيږېدنې په وخت مردار ولې نۀ شوم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_11.mp3', '', 1761754199, 1761754199),
(53005, 'Job 3:12', 'Job', 3, 12, 'زۀ ولې د مور په غېږ کښې وم، هغې ولې ما له سينه راکړې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_12.mp3', '', 1761754199, 1761754199),
(53006, 'Job 3:13', 'Job', 3, 13, 'کۀ زۀ مړ وے نو خاموش به وے، زۀ به اودۀ وے، او زۀ به په آرام وے', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_13.mp3', '', 1761754199, 1761754199),
(53007, 'Job 3:14', 'Job', 3, 14, 'د دُنيا د بادشاهانو او وزيرانو سره چې هغوئ د خپل ځان دپاره محلونه جوړ کړى وُو او اوس ترې نه کنډرات جوړ دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_14.mp3', '', 1761754199, 1761754199),
(53008, 'Job 3:15', 'Job', 3, 15, 'يا د شهزادګانو سره چې د هغوئ سره سرۀ زر وى، چې هغوئ خپل کورونه د سپينو زرو نه ډک کړى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_15.mp3', '', 1761754199, 1761754199),
(53009, 'Job 3:16', 'Job', 3, 16, 'يا زۀ د مړ پېدا شوى ماشوم په شان ولې ښخ نۀ شوم، د هغه ماشوم په شان چې رڼا يې هيڅکله نۀ وى ليدلې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_16.mp3', '', 1761754199, 1761754199),
(53010, 'Job 3:17', 'Job', 3, 17, 'چرته چې بدعمله خلق تکليف نۀ شى جوړولے، او ستړى خلق په آخر کښې آرام مومى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job3_verse_17.mp3', '', 1761754199, 1761754199);